use verus::prelude::*;

#[trusted]
#[requires(arr.len() > 0)]
// all rows of `arr` have the same length
#[requires(forall(|i: usize| i < arr.len() ==> arr[i].len() == arr[0].len()))]
// the result has #rows = #cols of the input
#[ensures(result.len() == arr[0].len())]
// each row of the result has length = #rows of the input
#[ensures(forall(|j: usize| j < result.len() ==> result[j].len() == arr.len()))]
// for every valid (i,j), result[j][i] == arr[i][j]
#[ensures(
    forall(|i: usize, j: usize|
        i < arr.len() &&
        j < arr[0].len() ==>
        result[j][i] == arr[i][j]
    )
)]
fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Number of rows and columns in the input
    let n_rows = arr.len();
    let n_cols = arr[0].len();

    // Build the transposed matrix: it will have n_cols rows,
    // each of length n_rows.
    let mut transposed = Vec::with_capacity(n_cols);
    for j in 0..n_cols {
        let mut new_row = Vec::with_capacity(n_rows);
        for i in 0..n_rows {
            new_row.push(arr[i][j]);
        }
        transposed.push(new_row);
    }

    transposed
}

